 function settlementPanel(){const credits=R.ensure(ops).credits,refunds=ops.rental?.refundObligations||[];return panel('Acertos, repasses e estornos',`<p class="caption">Registre apenas valores já conferidos. Repasses e devoluções baixam obrigações; não criam nova despesa. Estornos preservam a origem e podem reabrir um aluguel.</p>${credits.length?table(['Motorista / crédito','Disponível','Aplicado / pago','Ações'],credits.map(c=>{const summary=R.driverCredits(ops,c.driverId).records.find(r=>r.id===c.id);return `<tr><td>${esc(M.driver(ops,c.driverId).name)}<small>${esc(c.id)}</small></td><td>${cash(summary.available)}</td><td>${cash(c.applied||0)} / ${cash(c.paid||0)}</td><td>${summary.available>0?btn('Registrar repasse','settlement-credit-pay','',`data-id="${c.id}"`):''}${(c.paid||0)>0?btn('Conferir lucro recebido de volta','settlement-credit-recover','',`data-id="${c.id}"`):''}${(c.applied||0)>0?btn('Estornar abatimento','settlement-credit-reverse','',`data-id="${c.id}"`):''}</td></tr>`;}).join('')):'<p class="caption">Nenhum crédito gerado nesta sessão.</p>'}${refunds.length?table(['Devolução de aluguel','Saldo a devolver','Ação'],refunds.map(r=>`<tr><td>${esc(M.driver(ops,r.driverId).name)}<small>${esc(r.id)} · ${esc(r.chargeId)}</small></td><td>${cash(r.amount-r.paid)}</td><td>${r.paid<r.amount?btn('Registrar devolução','settlement-rental-refund','',`data-id="${r.id}"`):tag('Conferida','green')}</td></tr>`).join('')):''}`);}
 function settlementAction(action,e){if(!action.startsWith('settlement-'))return false;if(mode!=='admin')throw new RangeError('O acerto é conferido pela gestão.');const id=e.dataset.id,credit=R.ensure(ops).credits.find(c=>c.id===id),refund=ops.rental?.refundObligations.find(r=>r.id===id),title=F.ensure(ops).titles.find(t=>t.id===id);let body='';
  if(action==='settlement-credit-reverse'){const entries=ops.book.entries.filter(v=>v.creditId===id&&v.chargeId&&v.amount>0&&!v.reversalOf&&!ops.book.entries.some(r=>r.reversalOf===v.id));body=select('chargeId','Aluguel em que foi usado',entries[0]?.chargeId||'',entries.map(v=>[v.chargeId,v.chargeId+' · '+cash(v.amount)]));}
  else if(action==='settlement-credit-pay'||action==='settlement-credit-recover'||action==='settlement-rental-refund'){if(!credit&&!refund)throw new RangeError('Saldo não encontrado.');const max=refund?refund.amount-refund.paid:action==='settlement-credit-recover'?credit.paid:R.driverCredits(ops,credit.driverId).records.find(c=>c.id===id).available;body=input('amount','Valor conferido · R$',max,`type="number" min="0.01" max="${max}" step="0.01" required`)+select('accountId','Conta em que foi conferido','BANK-1',ops.finance.accounts.map(a=>[a.id,a.name]));}
  else if(action==='settlement-title-reverse'){if(!title)throw new RangeError('Título não encontrado.');body=row('Baixa original',esc(title.id)+' · '+cash(title.settledAmount??title.amount))+'<p>O estorno cria outro lançamento e reabre o saldo do compromisso. Originais e conciliações permanecem para conferência.</p>';}
  else return false;
  open(action==='settlement-credit-recover'?'Conferir valor recebido de volta':action.includes('reverse')?'Estornar com histórico':'Registrar pagamento conferido',`<form id="settlement-form"><input type="hidden" name="operation" value="${action}"><input type="hidden" name="entityId" value="${esc(id)}"><div class="notice">Registro demonstrativo. Não envia ou retira dinheiro do banco. Não faz desconto automático na caução.</div><div class="fields gap">${body}${input('date','Data conferida',K.operatingDate,'type="date" required')}${input('reference','Referência única','','required maxlength="100"')}</div><label class="field gap">Motivo / conferência<textarea name="note" required rows="3" maxlength="500"></textarea></label><label class="check gap"><input type="checkbox" name="confirmed" required>Conferi origem, valor, data e saldo.</label><div class="form-actions"><button type="submit" class="btn primary">Registrar conferência</button></div></form>`);return true;
 }
 function settlementSubmit(form,f){if(form.id!=='settlement-form')return false;if(mode!=='admin'||!f.has('confirmed'))throw new RangeError('A gestão precisa conferir o acerto.');const input={amount:Number(f.get('amount')),date:String(f.get('date')),accountId:String(f.get('accountId')||'BANK-1'),reference:String(f.get('reference')),note:String(f.get('note'))},id=String(f.get('entityId')),action=f.get('operation');if(action==='settlement-credit-pay')R.payAvailableCredit(ops,id,input);else if(action==='settlement-credit-recover')R.recoverPaidCredit(ops,id,input);else if(action==='settlement-credit-reverse')R.reverseCreditApplication(ops,id,String(f.get('chargeId')),input);else if(action==='settlement-rental-refund')R.refundRental(ops,id,input);else if(action==='settlement-title-reverse')F.reversePayment(ops,id,input);else return false;revision=null;close();render();persist();toast('Acerto registrado com origem e histórico. Confira o reflexo no livro e no extrato.');return true;}
